waves.point_eqs_str:
sample=pow(sample,.85);

c1=6.2831*t1/(1.1-sample);
c=cos(c1);
s=sin(c1);
c2=sqrt(1-sample);

ox=t7-.5*c2*c;
oy=t8-.625*c2*s;

x=t7+((ox-t7)*cos(t2)-(oy-t8)*sin(t2));
y=t8+((ox-t7)*sin(t2)+(oy-t8)*cos(t2));

inv=1/sqr(1.1-sample);
fdx=-.25*pow(1-sample,-.5)*c-c2*s*3.1415*t1*inv;
fdy=-.3125*c2*s+3.9268*c2*c*t1*inv;
invMag=1/sqrt(sqr(fdx)+sqr(fdy));
fdx=fdx*invMag;
fdy=fdy*invMag;

rdx=fdx*cos(1.5707+t2)-fdy*sin(1.5707+t2);
rdy=fdx*sin(1.5707+t2)+fdx*cos(1.5707+t2);
tt=rand(100)/100;
x=x+rdx*(.15*tt)*(1-sample);
y=y+rdy*(.15*tt)*(1-sample);

x=x*.55;
y=(y-.5)*.55+.5;

r=sample;
g=1-sample;
b=1;
a=below(sample,.995);


y=y+t3;

//plot x,y,z to point on circle
smp=sample*6.283;
xp=sin(smp )*0.05;
yp=cos(smp )*0.05;
zp=0;


//alter shape;
angy=sin(sample*6.28*4 +t1 )*6.28;
xq=xp*cos(angy) - zp*sin(angy);
zq=xp*sin(angy) + zp*cos(angy);
xp=xq;
zp=zq;


//rotate on y axis;
angy=t1*0.1;
xq=xp*cos(angy) - zp*sin(angy);
zq=xp*sin(angy) + zp*cos(angy);
xp=xq;
zp=zq;

//rotate on x axis
axs1 = sin(t1*0.15) + 1.6;
yq= yp*cos(axs1) - zp*sin(axs1);
zq= yp*sin(axs1) + zp*cos(axs1);
yp=yq;
zp=zq;

//rotate on y axis again
axs2 = sin(t1*0.1)*3.3;
xq=xp*cos(axs2) - zp*sin(axs2);
zq=xp*sin(axs2) + zp*cos(axs2);
xp=xq;
zp=zq;

//stretch y axis to compensate for aspect ratio
yp=yp*1.2;

//push forward into viewpace
zp=zp+2.1;

//project x,y,z into screenspace
xs=xp/zp;
ys=yp/zp;

//center 0,0 in middle of screen
x=xs+0.5+q4;
y=ys+0.5+q5;

r=1-q1;
g=1-q2;
b=1-q3;
